export function parseSquadsInstruction<TProgram extends string>(
  instruction: Instruction<TProgram> & InstructionWithData<ReadonlyUint8Array>,
): ParsedSquadsInstruction<TProgram> {
  const instructionType = identifySquadsInstruction(instruction);
  switch (instructionType) {
    case SquadsInstruction.ProgramConfigInit: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProgramConfigInit,
        ...parseProgramConfigInitInstruction(instruction),
      };
    }
    case SquadsInstruction.ProgramConfigSetAuthority: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProgramConfigSetAuthority,
        ...parseProgramConfigSetAuthorityInstruction(instruction),
      };
    }
    case SquadsInstruction.ProgramConfigSetMultisigCreationFee: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProgramConfigSetMultisigCreationFee,
        ...parseProgramConfigSetMultisigCreationFeeInstruction(instruction),
      };
    }
    case SquadsInstruction.ProgramConfigSetTreasury: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProgramConfigSetTreasury,
        ...parseProgramConfigSetTreasuryInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigCreate: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigCreate,
        ...parseMultisigCreateInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigCreateV2: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigCreateV2,
        ...parseMultisigCreateV2Instruction(instruction),
      };
    }
    case SquadsInstruction.MultisigAddMember: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigAddMember,
        ...parseMultisigAddMemberInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigRemoveMember: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigRemoveMember,
        ...parseMultisigRemoveMemberInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigSetTimeLock: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigSetTimeLock,
        ...parseMultisigSetTimeLockInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigChangeThreshold: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigChangeThreshold,
        ...parseMultisigChangeThresholdInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigSetConfigAuthority: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigSetConfigAuthority,
        ...parseMultisigSetConfigAuthorityInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigSetRentCollector: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigSetRentCollector,
        ...parseMultisigSetRentCollectorInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigAddSpendingLimit: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigAddSpendingLimit,
        ...parseMultisigAddSpendingLimitInstruction(instruction),
      };
    }
    case SquadsInstruction.MultisigRemoveSpendingLimit: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.MultisigRemoveSpendingLimit,
        ...parseMultisigRemoveSpendingLimitInstruction(instruction),
      };
    }
    case SquadsInstruction.ConfigTransactionCreate: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ConfigTransactionCreate,
        ...parseConfigTransactionCreateInstruction(instruction),
      };
    }
    case SquadsInstruction.ConfigTransactionExecute: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ConfigTransactionExecute,
        ...parseConfigTransactionExecuteInstruction(instruction),
      };
    }
    case SquadsInstruction.VaultTransactionCreate: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.VaultTransactionCreate,
        ...parseVaultTransactionCreateInstruction(instruction),
      };
    }
    case SquadsInstruction.TransactionBufferCreate: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.TransactionBufferCreate,
        ...parseTransactionBufferCreateInstruction(instruction),
      };
    }
    case SquadsInstruction.TransactionBufferClose: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.TransactionBufferClose,
        ...parseTransactionBufferCloseInstruction(instruction),
      };
    }
    case SquadsInstruction.TransactionBufferExtend: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.TransactionBufferExtend,
        ...parseTransactionBufferExtendInstruction(instruction),
      };
    }
    case SquadsInstruction.VaultTransactionCreateFromBuffer: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.VaultTransactionCreateFromBuffer,
        ...parseVaultTransactionCreateFromBufferInstruction(instruction),
      };
    }
    case SquadsInstruction.VaultTransactionExecute: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.VaultTransactionExecute,
        ...parseVaultTransactionExecuteInstruction(instruction),
      };
    }
    case SquadsInstruction.BatchCreate: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.BatchCreate,
        ...parseBatchCreateInstruction(instruction),
      };
    }
    case SquadsInstruction.BatchAddTransaction: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.BatchAddTransaction,
        ...parseBatchAddTransactionInstruction(instruction),
      };
    }
    case SquadsInstruction.BatchExecuteTransaction: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.BatchExecuteTransaction,
        ...parseBatchExecuteTransactionInstruction(instruction),
      };
    }
    case SquadsInstruction.ProposalCreate: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProposalCreate,
        ...parseProposalCreateInstruction(instruction),
      };
    }
    case SquadsInstruction.ProposalActivate: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProposalActivate,
        ...parseProposalActivateInstruction(instruction),
      };
    }
    case SquadsInstruction.ProposalApprove: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProposalApprove,
        ...parseProposalApproveInstruction(instruction),
      };
    }
    case SquadsInstruction.ProposalReject: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProposalReject,
        ...parseProposalRejectInstruction(instruction),
      };
    }
    case SquadsInstruction.ProposalCancel: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProposalCancel,
        ...parseProposalCancelInstruction(instruction),
      };
    }
    case SquadsInstruction.ProposalCancelV2: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ProposalCancelV2,
        ...parseProposalCancelV2Instruction(instruction),
      };
    }
    case SquadsInstruction.SpendingLimitUse: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.SpendingLimitUse,
        ...parseSpendingLimitUseInstruction(instruction),
      };
    }
    case SquadsInstruction.ConfigTransactionAccountsClose: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.ConfigTransactionAccountsClose,
        ...parseConfigTransactionAccountsCloseInstruction(instruction),
      };
    }
    case SquadsInstruction.VaultTransactionAccountsClose: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.VaultTransactionAccountsClose,
        ...parseVaultTransactionAccountsCloseInstruction(instruction),
      };
    }
    case SquadsInstruction.VaultBatchTransactionAccountClose: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.VaultBatchTransactionAccountClose,
        ...parseVaultBatchTransactionAccountCloseInstruction(instruction),
      };
    }
    case SquadsInstruction.BatchAccountsClose: {
      assertIsInstructionWithAccounts(instruction);
      return {
        instructionType: SquadsInstruction.BatchAccountsClose,
        ...parseBatchAccountsCloseInstruction(instruction),
      };
    }
    default:
      throw new SolanaError(
        SOLANA_ERROR__PROGRAM_CLIENTS__UNRECOGNIZED_INSTRUCTION_TYPE,
        { instructionType: instructionType as string, programName: "squads" },
      );
  }
}

